export type ParsedCloseCircularInstruction<
  TProgram extends string = typeof PENNY_POST_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>
  accounts: {
    caller: TAccountMetas[0]
    sponsor: TAccountMetas[1]
    circular: TAccountMetas[2]
    potVault: TAccountMetas[3]
    sponsorToken?: TAccountMetas[4] | undefined
    postOffice: TAccountMetas[5]
    postageMint: TAccountMetas[6]
    tokenProgram: TAccountMetas[7]
  }
  data: CloseCircularInstructionData
}

export function parseCloseCircularInstruction<TProgram extends string, TAccountMetas extends readonly AccountMeta[]>(
  instruction: Instruction<TProgram> & InstructionWithAccounts<TAccountMetas> & InstructionWithData<ReadonlyUint8Array>,
): ParsedCloseCircularInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 8) {
    throw new SolanaError(SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS, {
      actualAccountMetas: instruction.accounts.length,
      expectedAccountMetas: 8,
    })
  }
  let accountIndex = 0
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!
    accountIndex += 1
    return accountMeta
  }
  const getNextOptionalAccount = () => {
    const accountMeta = getNextAccount()
    return accountMeta.address === PENNY_POST_PROGRAM_ADDRESS ? undefined : accountMeta
  }
  return {
    programAddress: instruction.programAddress,
    accounts: {
      caller: getNextAccount(),
      sponsor: getNextAccount(),
      circular: getNextAccount(),
      potVault: getNextAccount(),
      sponsorToken: getNextOptionalAccount(),
      postOffice: getNextAccount(),
      postageMint: getNextAccount(),
      tokenProgram: getNextAccount(),
    },
    data: getCloseCircularInstructionDataDecoder().decode(instruction.data),
  }
}
